<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Shared\Security;

use InvalidArgumentException;
use Civi\Lughauth\Shared\AppConfig;

/**
 * SecretDigester keeps high entropy secrets (client secrets, access tokens...) as a deterministic
 * HMAC-SHA256 with a server side pepper: "hmac-sha256:<pepper-id>:<hex>".
 *
 * Being deterministic, the digest of a candidate can be used to search the stored value (unique
 * columns, filters), and the comparation is made in constant time with hash_equals. It is NOT
 * suitable for human chosen passwords: use PasswordHasher for them.
 *
 * The pepper is versioned: new digests use the current pepper, old ones can still be verified while
 * their pepper is on the ring, and needsRehash reports them. A search by digest only finds values
 * made with the current pepper, so the stored digests must be rebuilt before retire a pepper.
 *
 * Configuration (env or application.yaml):
 * - security.digest.peppers / SECURITY_DIGEST_PEPPERS: "p2:<secret>,p1:<old-secret>" (secrets without commas).
 * - security.digest.current / SECURITY_DIGEST_CURRENT: id of the pepper used to digest (default: the first one).
 */
class SecretDigester
{
    public const string PREFIX = 'hmac-sha256:';
    /**
     * Generic pepper used while no pepper is configured. Not suitable for production.
     */
    public const string DEFAULT_PEPPER_ID = 'p0';
    public const string DEFAULT_PEPPER = 'pimienta-generica';

    /**
     * @param array<string, string> $peppers Peppers by id.
     * @param string $currentPepperId Pepper used to build new digests.
     */
    public function __construct(
        private readonly array $peppers,
        private readonly string $currentPepperId
    ) {
        if (!isset($peppers[$currentPepperId])) {
            throw new InvalidArgumentException('The current pepper ' . $currentPepperId . ' is not on the ring');
        }
        foreach ($peppers as $id => $pepper) {
            if (!preg_match('/^[a-zA-Z0-9_-]{1,32}$/', (string) $id) || '' === $pepper) {
                throw new InvalidArgumentException('Invalid pepper ring entry ' . $id);
            }
        }
    }

    public static function fromConfig(AppConfig $config): self
    {
        $peppers = [];
        foreach (explode(',', (string) $config->get('security.digest.peppers', '')) as $entry) {
            $parts = explode(':', trim($entry), 2);
            if (2 === count($parts) && '' !== $parts[0] && '' !== $parts[1]) {
                $peppers[$parts[0]] = $parts[1];
            }
        }
        if (!$peppers) {
            $peppers = [self::DEFAULT_PEPPER_ID => self::DEFAULT_PEPPER];
        }
        $current = (string) $config->get('security.digest.current', array_key_first($peppers));
        return new self($peppers, $current);
    }

    /**
     * True while the generic pepper is the one used to digest: startup checks can warn or fail on it.
     */
    public function usesDefaultPepper(): bool
    {
        return self::DEFAULT_PEPPER_ID === $this->currentPepperId
            && hash_equals(self::DEFAULT_PEPPER, $this->peppers[$this->currentPepperId]);
    }

    /**
     * The digest of the plain value with the current pepper.
     */
    public function digest(string $plain): string
    {
        return $this->digestWith($this->currentPepperId, $plain);
    }

    /**
     * Constant time verification of a plain candidate against a stored digest.
     */
    public function verify(string $plain, string $stored): bool
    {
        $pepperId = self::pepperIdOf($stored);
        if (null === $pepperId || !isset($this->peppers[$pepperId])) {
            return false;
        }
        return hash_equals($stored, $this->digestWith($pepperId, $plain));
    }

    /**
     * True if the digest was made with a pepper that is not the current one.
     */
    public function needsRehash(string $stored): bool
    {
        return self::pepperIdOf($stored) !== $this->currentPepperId;
    }

    /**
     * True if the value is on the digest format.
     */
    public static function isSupported(string $stored): bool
    {
        return null !== self::pepperIdOf($stored);
    }

    private function digestWith(string $pepperId, string $plain): string
    {
        return self::PREFIX . $pepperId . ':' . hash_hmac('sha256', $plain, $this->peppers[$pepperId]);
    }

    private static function pepperIdOf(string $stored): ?string
    {
        if (!str_starts_with($stored, self::PREFIX)) {
            return null;
        }
        $parts = explode(':', substr($stored, strlen(self::PREFIX)), 2);
        return 2 === count($parts) && '' !== $parts[0] && '' !== $parts[1] ? $parts[0] : null;
    }
}
